<script setup lang="ts">
import{computed}from'vue';import{useEngine}from'../stores/engine';import{outputLabel}from'../types/engine';import Icon from'../components/Icon.vue';
const e=useEngine();const river=computed(()=>e.snapshot?.state?.river);const primary=computed(()=>e.inputs.find(i=>i.id===river.value?.producer));const backups=computed(()=>e.inputs.filter(i=>river.value?.references?.includes(i.id)&&i.id!==river.value?.producer));const outputs=computed(()=>e.snapshot?.state?.speakers?.filter(s=>s.selected)||[]);const selected=computed(()=>e.inputs.filter(i=>e.snapshot?.state?.instances?.[i.id]?.selected));
</script>
<template><header class="page-header"><div><h1>River 中心</h1><p class="page-description">一个主音源，其他有效输入随时待命。</p></div><span class="badge" :class="primary&&!river?.paused?'blue':'neutral'"><span class="status-dot" :class="{live:primary&&!river?.paused}"></span>{{river?.paused?'已暂停':primary?'音频正在运行':'等待音频输入'}}</span></header><p v-if="e.snapshot?.state_error" class="notice error"><Icon name="warning"/><span>{{e.snapshot.state_error}}</span></p><section class="river-summary panel"><span class="river-hero-icon"><Icon name="river" :size="42"/></span><div><p class="eyebrow">当前主音源</p><h2>{{primary?.name||'暂无主音源'}}</h2><p>{{river?.paused?'已暂停，接收器连接保持中。':primary?'由 Engine 选择，音频沿同一条 River 发送。':'从 AirPlay 选择接收器后，这里会显示真实运行状态。'}}</p></div><span class="badge neutral">{{outputs.length}} 台参与投放</span></section><section class="two-column"><article class="panel"><div class="panel-heading"><div><h2>备用输入</h2><p>有效但未被选为主源的输入</p></div><Icon name="inputs"/></div><div v-if="!backups.length" class="small-empty">暂无备用输入</div><div v-for="input in backups" :key="input.id" class="compact-row"><span class="mini-avatar"><Icon name="inputs" :size="18"/></span><b>{{input.name}}</b><span class="badge teal">待命</span></div></article><article class="panel"><div class="panel-heading"><div><h2>投放音箱</h2><p>根据实际选中与 Sender 状态显示</p></div><Icon name="speaker"/></div><div v-if="!outputs.length" class="small-empty">暂无选中的音箱</div><div v-for="speaker in outputs" :key="speaker.speaker_id" class="compact-row"><span class="mini-avatar"><Icon name="speaker" :size="18"/></span><b>{{speaker.display_name}}</b><span class="badge" :class="speaker.playback_state==='playing'?'blue':'neutral'">{{outputLabel(speaker)}}</span></div></article></section><section v-if="selected.length" class="panel"><div class="panel-heading"><div><h2>已选中入口</h2><p>连接参与情况与主源、备用状态分别记录</p></div></div><div class="chip-list"><span v-for="input in selected" :key="input.id" class="device-chip"><Icon name="inputs" :size="15"/>{{input.name}}<small v-if="e.snapshot?.state?.instances?.[input.id]?.paused">已暂停</small></span></div></section><details class="panel advanced-panel"><summary><span><Icon name="info" :size="18"/>运行诊断</span><Icon name="chevron" :size="16"/></summary><dl class="settings-facts"><dt>数据面</dt><dd>{{e.snapshot?.state?.kernel?.state||'不可用'}}</dd><dt>内容代次</dt><dd>{{river?.generation??'未报告'}}</dd><dt>输出字节</dt><dd>{{river?.output_bytes?.toLocaleString()??'未报告'}}</dd></dl><p class="field-help">主源选择、备用切换及音箱集合由内核管理。当前 API 未提供完整的队列水位和切换事件流；详细问题可导出诊断查看。</p><RouterLink class="button secondary" to="/settings"><Icon name="file" :size="16"/>日志与诊断</RouterLink></details></template>
